  \left.\frac{\partial \Gamma}{\partial X}\right|_{H} = q \mathrm{Tr}\parenth{ X^{q-1} H}, \left.\frac{\partial^2 \Gamma}{\partial X \partial X}\right|_{H_1, H_2} = q \sum_{a=0}^{q-2} \mathrm{Tr}\parenth{X^a H_2 X^{q-2-a} H_1}.
\end{align*}

Using the above derivatives and It\^o's formula, we obtain
\begin{align}
  \label{eq:poten_two_derivative_intermediate}
  d\Gamma_t = d \mathrm{Tr}\parenth{Q_t^q} = q \mathrm{Tr}\parenth{ Q_t^{q-1} d Q_t} + \frac{q}{2} \sum_{a = 0}^{q-2} \sum_{i,j,k,l=1}^{\ensuremath{d}} \mathrm{Tr}\parenth{Q_t^a E_{ij} Q_t^{q-2-a} E_{kl}} d\brackets{Q_{ij}, Q_{kl}}_t,
\end{align}
where $E_{ij}$ is the matrix that takes $1$ at the entry $(i, j)$ and $0$ otherwise and $Q_{ij, t}$ is the stochastic process defined by the $(i,j)$ entry of $Q_t$.

\begin{align}
  \label{eq:poten_two_derivative_intermediate}
  d\Gamma_t = d \mathrm{Tr}\parenth{Q_t^q} = q \mathrm{Tr}\parenth{ Q_t^{q-1} d Q_t} + \frac{q}{2} \sum_{a = 0}^{q-2} \sum_{i,j,k,l=1}^{\ensuremath{d}} \mathrm{Tr}\parenth{Q_t^a E_{ij} Q_t^{q-2-a} E_{kl}} d\brackets{Q_{ij}, Q_{kl}}_t,
\end{align}

\begin{align*}
  dQ_t &= \int  A^{-1/2} \parenth{x - \mu_t} \parenth{x - \mu_t}^\top A^{-1/2} \parenth{\parenth{x-\mu_t}^\top A^{-1/2} dW_t} p_t(x) dx - Q_t^2 dt, \\
  d\brackets{Q_{ij}, Q_{kl}}_t &= \int \int z(x)_i z(x)_j z(y)_k z(y)_l (x-\mu_t)^\top A^{-1} (y-\mu_t) p_t(x) p_t(y)dx dy dt,
\end{align*}

\begin{align*}
  d\Gamma_t &=  q \int \parenth{x-\mu_t}^\top A^{-1/2} \parenth{Q_t}^{q-1} A^{-1/2} \parenth{x-\mu_t} \parenth{x-\mu_t}^\top A^{-1/2} dW_t p_t(x) dx \notag \\
  &- q \mathrm{Tr}\parenth{Q_t^{q+1} } dt \notag \\
  &+ \frac{q}{2} \sum_{a = 0}^{q-2} \int \int \parenth{x-\mu_t}^\top A^{-1/2} Q_t^{a} A^{-1/2} \parenth{y-\mu_t} \notag \\
  &\cdot \parenth{x-\mu_t}^\top A^{-1/2} Q_t^{q-2-a} A^{-1/2} \parenth{y-\mu_t} \parenth{x-\mu_t}^\top A^{-1} \parenth{y-\mu_t} p_t(x) p_t(y) dx dy dt.
\end{align*}
